/* Contactless Card Payment at a Modern Checkout Terminal
 * Self-contained Canvas artwork. Time is in seconds; the cycle is 20 seconds.
 * Call draw(ctx, time, width, height). Recommended frame rate: 60 fps.
 * Video encoder target: 100000000 bits/second, with a verified minimum of 100 Mbps.
 * JavaScript frames themselves do not have a video bitrate.
 */
const POS_SCENE_01 = (() => {
  'use strict';
  const C = {"bg": "#F1F3EE", "paper": "#FFFFFF", "ink": "#233644", "muted": "#6A7B82", "line": "#CDD8D7", "body": "#EEF2F1", "body2": "#DCE5E4", "side": "#4B6270", "accent": "#327D83", "green": "#39845F", "card": "#244855", "card2": "#436977"};
  const TAU = Math.PI * 2;
  const fonts = 'Arial, Helvetica, "Nimbus Sans", "DejaVu Sans", sans-serif';
  const measurements = new Map();
  const clamp = v => Math.max(0, Math.min(1, v));
  const ease = v => { v = clamp(v); return v < .5 ? 4 * v * v * v : 1 - Math.pow(-2 * v + 2, 3) / 2; };
  const phase = (t, a, b) => ease((t - a) / (b - a));
  const mix = (a, b, p) => a + (b - a) * p;
  const travel = (t, a, b, c, d) => phase(t, a, b) * (1 - phase(t, c, d));
  const windowAlpha = (t, a, b, c, d) => travel(t, a, b, c, d);
  function blend(a, b, p) {
    p = clamp(p);
    const ca = parseInt(a.slice(1), 16), cb = parseInt(b.slice(1), 16);
    const r = Math.round(mix(ca >> 16, cb >> 16, p));
    const g = Math.round(mix((ca >> 8) & 255, (cb >> 8) & 255, p));
    const bl = Math.round(mix(ca & 255, cb & 255, p));
    return '#' + ((r << 16) | (g << 8) | bl).toString(16).padStart(6, '0');
  }
  function layer(ctx, opacity, fn) {
    if (opacity <= .00001) return;
    ctx.save(); ctx.globalAlpha *= clamp(opacity); fn(); ctx.restore();
  }
  function roundedPath(ctx, x, y, w, h, r) {
    r = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath(); ctx.moveTo(x + r, y); ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r); ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r); ctx.quadraticCurveTo(x, y, x + r, y); ctx.closePath();
  }
  function box(ctx, x, y, w, h, r, fill, stroke = C.ink, lw = 3) {
    roundedPath(ctx, x, y, w, h, r);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke && lw > 0) { ctx.strokeStyle = stroke; ctx.lineWidth = lw; ctx.stroke(); }
  }
  function line(ctx, x1, y1, x2, y2, color = C.ink, width = 3) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.strokeStyle = color; ctx.lineWidth = width; ctx.stroke();
  }
  function circle(ctx, x, y, r, fill, stroke = null, width = 3) {
    ctx.beginPath(); ctx.arc(x, y, r, 0, TAU);
    if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = width; ctx.stroke(); }
  }
  function polygon(ctx, points, fill, stroke = C.ink, width = 3) {
    ctx.beginPath(); ctx.moveTo(points[0][0], points[0][1]);
    for (let i = 1; i < points.length; i++) ctx.lineTo(points[i][0], points[i][1]);
    ctx.closePath(); if (fill) { ctx.fillStyle = fill; ctx.fill(); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = width; ctx.stroke(); }
  }
  function matte(ctx, x, y, w, h, a, b) {
    const g = ctx.createLinearGradient(x, y, x + w, y + h); g.addColorStop(0, a); g.addColorStop(1, b); return g;
  }
  function label(ctx, value, x, y, size = 20, color = C.ink, align = 'left', maxWidth = 0, weight = 600) {
    const str = String(value);
    let fontSize = size, m;
    while (true) {
      ctx.font = weight + ' ' + fontSize.toFixed(2) + 'px ' + fonts;
      const key = ctx.font + '|' + str;
      m = measurements.get(key);
      if (!m) { const a = ctx.measureText(str); m = {w: a.width, a: a.actualBoundingBoxAscent || fontSize * .75, d: a.actualBoundingBoxDescent || 0}; measurements.set(key, m); }
      if (!maxWidth || m.w <= maxWidth || fontSize <= 12) break;
      fontSize = Math.max(12, fontSize * Math.min(.97, maxWidth / m.w));
    }
    ctx.fillStyle = color; ctx.textAlign = align; ctx.textBaseline = 'alphabetic';
    ctx.fillText(str, x, y + (m.a - m.d) / 2);
  }
  function check(ctx, x, y, size, color = C.green, p = 1) {
    const pts = [[x - size * .42, y], [x - size * .08, y + size * .30], [x + size * .48, y - size * .32]];
    ctx.beginPath(); ctx.moveTo(...pts[0]);
    if (p < .4) ctx.lineTo(mix(pts[0][0], pts[1][0], p / .4), mix(pts[0][1], pts[1][1], p / .4));
    else { ctx.lineTo(...pts[1]); ctx.lineTo(mix(pts[1][0], pts[2][0], (p - .4) / .6), mix(pts[1][1], pts[2][1], (p - .4) / .6)); }
    ctx.strokeStyle = color; ctx.lineWidth = Math.max(2.5, size * .14); ctx.stroke();
  }
  function chip(ctx, x, y, w = 54, h = 42) {
    box(ctx, x, y, w, h, 7, '#E8C991', C.ink, 2);
    line(ctx, x + w * .34, y + 2, x + w * .34, y + h - 2, C.ink, 1.6);
    line(ctx, x + w * .66, y + 2, x + w * .66, y + h - 2, C.ink, 1.6);
    line(ctx, x + 2, y + h * .5, x + w - 2, y + h * .5, C.ink, 1.6);
  }
  function wireless(ctx, x, y, size = 28, color = C.ink, opacity = 1) {
    layer(ctx, opacity, () => {
      for (let i = 1; i <= 3; i++) { ctx.beginPath(); ctx.arc(x - size * .65, y, size * i / 3, -.62, .62); ctx.strokeStyle = color; ctx.lineWidth = Math.max(2, size * .10); ctx.stroke(); }
    });
  }
  function activity(ctx, x, y, t, r = 12, color = C.accent) {
    circle(ctx, x, y, r, null, C.line, 2.5);
    const angle = TAU * (t / 5);
    ctx.beginPath(); ctx.arc(x, y, r, angle, angle + Math.PI * .70); ctx.strokeStyle = color; ctx.lineWidth = 3; ctx.stroke();
  }
  function state(t, processAt = 8, approveAt = 13, resetAt = 18.1) {
    const a = phase(t, processAt, processAt + .8), b = phase(t, approveAt, approveAt + .8), r = phase(t, resetAt, 19.8);
    const w = [1 - a + b * r, a * (1 - b), b * (1 - r)];
    let index = 0; for (let i = 1; i < 3; i++) if (w[i] > w[index]) index = i;
    return {w, index, alpha: clamp((w[index] - .5) * 2), progress: phase(t, processAt + .8, approveAt)};
  }
  function badge(ctx, x, y, w, h, text, color = C.accent, alpha = 1) {
    box(ctx, x, y, w, h, h / 2, blend(C.paper, color, .12), null);
    layer(ctx, alpha, () => label(ctx, text, x + w / 2, y + h / 2, 17, color, 'center', w - 26, 700));
  }
  function header(ctx, title, subtitle, t) {
    label(ctx, 'CONTACTLESS COMMERCE', 130, 80, 16, C.muted, 'left', 1120, 700);
    label(ctx, title, 130, 132, 44, C.ink, 'left', 1430, 700);
    label(ctx, subtitle, 130, 181, 20, C.muted, 'left', 1440, 400);
    activity(ctx, 1730, 108, t, 13);
    label(ctx, 'LINK ACTIVE', 1685, 150, 14, C.muted, 'center', 160, 600);
  }
  function counter(ctx) {
    box(ctx, 100, 911, 1720, 20, 10, C.line, null);
    line(ctx, 130, 979, 1790, 979, C.line, 2);
    label(ctx, 'CARD', 130, 1011, 14, C.muted, 'left', 160, 600);
    label(ctx, 'CONTACTLESS', 590, 1011, 14, C.muted, 'left', 240, 600);
    label(ctx, 'VERIFIED', 1080, 1011, 14, C.muted, 'left', 240, 600);
    label(ctx, 'DIGITAL COMMERCE', 1790, 1011, 14, C.muted, 'right', 300, 600);
  }
  function paymentCard(ctx, x, y, w = 300, h = 180, variant = 0) {
    const a = variant ? C.accent : C.card, b = variant ? blend(C.accent, C.card, .50) : C.card2;
    box(ctx, x, y, w, h, 20, matte(ctx, x, y, w, h, a, b), C.ink, 4);
    label(ctx, 'PAYMENT CARD', x + 24, y + 29, 15, '#FFFFFF', 'left', w - 95, 700);
    chip(ctx, x + 24, y + 59, 53, 40);
    wireless(ctx, x + w - 42, y + 79, 23, '#FFFFFF');
    for (let i = 0; i < 8; i++) circle(ctx, x + 26 + i * 13, y + 127, 2.6, '#FFFFFF');
    label(ctx, '2084', x + 143, y + 127, 18, '#FFFFFF', 'left', 80, 600);
    line(ctx, x + 24, y + h - 24, x + 102, y + h - 24, blend(a, '#FFFFFF', .62), 3);
    line(ctx, x + 120, y + h - 24, x + 160, y + h - 24, blend(a, '#FFFFFF', .38), 3);
  }
  function standardScreen(ctx, x, y, w, h, t, opt = {}) {
    const s = opt.state || state(t);
    label(ctx, opt.top || 'TOTAL DUE', x + w / 2, y + 31, 14, C.muted, 'center', w - 40, 700);
    label(ctx, opt.amount || '$48.90', x + w / 2, y + 81, 41, C.ink, 'center', w - 38, 700);
    const texts = opt.labels || ['READY TO TAP', 'PROCESSING', 'PAYMENT APPROVED'];
    const color = blend(C.accent, C.green, s.w[2]);
    box(ctx, x + 15, y + 119, w - 30, 44, 12, blend(C.paper, color, .11), null);
    layer(ctx, s.alpha, () => label(ctx, texts[s.index], x + w / 2, y + 141, 18, color, 'center', w - 54, 700));
    line(ctx, x + 25, y + 188, x + w - 25, y + 188, C.line, 4);
    const p = s.w[2] + s.w[1] * s.progress;
    if (p > .0001) line(ctx, x + 25, y + 188, x + 25 + (w - 50) * p, y + 188, color, 4);
  }
  function terminal(ctx, x, y, t, opt = {}) {
    ctx.save(); ctx.translate(x, y); ctx.scale(opt.scale || 1, opt.scale || 1);
    box(ctx, 0, 0, 400, 620, 36, matte(ctx, 0, 0, 400, 620, C.body, C.body2), C.ink, 5);
    box(ctx, 388, 30, 6, 560, 3, C.side, null);
    circle(ctx, 18, 24, 3, C.muted); circle(ctx, 18, 594, 3, C.muted);
    label(ctx, 'PAYMENT TERMINAL', 29, 34, 14, C.ink, 'left', 256, 700);
    box(ctx, 330, 25, 34, 16, 3, C.paper, C.muted, 1.6);
    box(ctx, 334, 29, 22, 8, 1, C.green, null); line(ctx, 366, 30, 366, 36, C.muted, 2);
    box(ctx, 26, 72, 348, 210, 17, C.paper, C.ink, 3);
    ctx.save(); roundedPath(ctx, 28, 74, 344, 206, 15); ctx.clip();
    if (opt.screen) opt.screen(ctx, 26, 72, 348, 210); else standardScreen(ctx, 26, 72, 348, 210, t, opt);
    ctx.restore();
    box(ctx, 26, 304, 348, 66, 13, blend(C.paper, C.accent, .06), C.line, 2);
    label(ctx, 'CONTACTLESS', 48, 337, 17, C.ink, 'left', 190, 700);
    wireless(ctx, 329, 337, 26, C.accent);
    const rows = [['1', '2', '3'], ['4', '5', '6'], ['7', '8', '9'], ['C', '0', 'OK']];
    for (let row = 0; row < 4; row++) for (let col = 0; col < 3; col++) {
      const bx = 26 + col * 122, by = 396 + row * 50;
      const color = row === 3 && col === 2 ? blend(C.paper, C.green, .20) : row === 3 && col === 0 ? '#F4E0D7' : C.paper;
      box(ctx, bx, by, 104, 38, 9, color, C.line, 2);
      label(ctx, rows[row][col], bx + 52, by + 19, row === 3 ? 16 : 19, C.ink, 'center', 78, 600);
    }
    label(ctx, 'NFC', 200, 601, 12, C.muted, 'center', 100, 700);
    ctx.restore();
  }
  function summary(ctx, x, y, w, h, opt = {}) {
    box(ctx, x, y, w, h, 24, C.paper, C.line, 3);
    label(ctx, opt.title || 'TRANSACTION SUMMARY', x + 28, y + 35, 17, C.muted, 'left', w - 56, 700);
    label(ctx, opt.amount || '$48.90', x + 28, y + 94, 47, C.ink, 'left', w - 56, 700);
    line(ctx, x + 28, y + 135, x + w - 28, y + 135, C.line, 2);
    const rows = opt.rows || [['Order', '0482'], ['Payment', 'Contactless'], ['Status', 'Ready']];
    rows.forEach((row, i) => {
      const yy = y + 169 + i * 39;
      label(ctx, row[0], x + 28, yy, 18, C.muted, 'left', w * .43 - 28, 400);
      label(ctx, row[1], x + w - 28, yy, 18, C.ink, 'right', w * .50 - 28, 600);
    });
  }
  function barcode(ctx, x, y, w, h) {
    const units = [2,1,1,3,2,2,1,1,3,1,2,1,2,3,1,1,2,2,3,1,1,2,1,3,2,1,2,2];
    const total = units.reduce((a, b) => a + b, 0) + units.length;
    const u = w / total; let xx = x;
    units.forEach(v => { ctx.fillStyle = C.ink; ctx.fillRect(xx, y, v * u, h); xx += (v + 1) * u; });
  }
  function receipt(ctx, x, y, w, h, amount = '$48.90', title = 'PAYMENT RECEIPT') {
    const pts = [[x, y], [x + w, y], [x + w, y + h - 7]];
    for (let i = 0; i <= 20; i++) pts.push([x + w - w * i / 20, y + h - (i % 2 ? 0 : 7)]);
    pts.push([x, y]); polygon(ctx, pts, '#FFFFFF', C.ink, 2.5);
    label(ctx, title, x + w / 2, y + 24, 15, C.ink, 'center', w - 28, 700);
    line(ctx, x + 20, y + 47, x + w - 20, y + 47, C.line, 1.5);
    for (let i = 0; i < 2; i++) {
      line(ctx, x + 20, y + 64 + i * 17, x + w * .47, y + 64 + i * 17, C.muted, 2);
      line(ctx, x + w * .73, y + 64 + i * 17, x + w - 20, y + 64 + i * 17, C.muted, 2);
    }
    label(ctx, amount, x + w / 2, y + 111, 25, C.ink, 'center', w - 32, 700);
    barcode(ctx, x + 23, y + h - 50, w - 46, 24);
  }
  function printer(ctx, x, y, t, opt = {}) {
    const w = opt.width || 360, h = 200, paperW = w - 100, paperH = 205;
    box(ctx, x, y, w, h, 27, matte(ctx, x, y, w, h, C.body, C.body2), C.ink, 4);
    box(ctx, x + 16, y + 17, w - 32, 33, 9, C.side, null);
    const slotY = y + 51;
    const reveal = phase(t, opt.start || 14, opt.end || 17.2);
    const opacity = 1 - phase(t, 18.2, 19.7);
    layer(ctx, opacity, () => {
      ctx.save(); ctx.beginPath(); ctx.rect(x + 48, slotY + 2, paperW + 4, paperH + 6); ctx.clip();
      receipt(ctx, x + 50, slotY - paperH + paperH * reveal, paperW, paperH, opt.amount, opt.title);
      ctx.restore();
    });
    line(ctx, x + 44, slotY, x + w - 44, slotY, C.ink, 5);
    activity(ctx, x + w - 24, y + 104, t, 7);
    line(ctx, x + 16, y + h - 25, x + 31, y + h - 25, C.muted, 3);
  }
  function phone(ctx, x, y, t, opt = {}) {
    const w = 235, h = 402;
    box(ctx, x, y, w, h, 30, C.side, C.ink, 4);
    box(ctx, x + 12, y + 14, w - 24, h - 28, 22, C.paper, null);
    box(ctx, x + 80, y + 22, 75, 7, 3, C.ink, null);
    label(ctx, 'MOBILE WALLET', x + w / 2, y + 63, 16, C.ink, 'center', w - 36, 700);
    const cx = x + 24, cy = y + 94;
    box(ctx, cx, cy, w - 48, 110, 14, matte(ctx, cx, cy, w - 48, 110, C.card, C.card2), C.ink, 2);
    chip(ctx, cx + 15, cy + 17, 36, 28); wireless(ctx, cx + 157, cy + 35, 17, '#FFFFFF');
    label(ctx, 'DIGITAL CARD', cx + 15, cy + 84, 13, '#FFFFFF', 'left', w - 78, 600);
    label(ctx, opt.amount || '$48.90', x + w / 2, y + 241, 31, C.ink, 'center', w - 40, 700);
    const s = opt.state || state(t, 8, 13);
    badge(ctx, x + 24, y + 275, w - 48, 38, ['READY', 'CONNECTING', 'PAID'][s.index], blend(C.accent, C.green, s.w[2]), s.alpha);
    activity(ctx, x + w / 2, y + 342, t, 12);
    line(ctx, x + 88, y + h - 27, x + 147, y + h - 27, C.muted, 3);
  }
  function parcel(ctx, x, y, w = 320, h = 240) {
    const dx = 35, dy = 30;
    polygon(ctx, [[x, y], [x + dx, y - dy], [x + w + dx, y - dy], [x + w, y]], '#DFC19B', C.ink, 3);
    polygon(ctx, [[x + w, y], [x + w + dx, y - dy], [x + w + dx, y + h - dy], [x + w, y + h]], '#C6A780', C.ink, 3);
    box(ctx, x, y, w, h, 2, '#E8CCA7', C.ink, 3);
    polygon(ctx, [[x + w * .45, y], [x + w * .45 + dx, y - dy], [x + w * .57 + dx, y - dy], [x + w * .57, y]], '#F5E2BC', C.ink, 1.5);
    ctx.fillStyle = '#F5E2BC'; ctx.fillRect(x + w * .45, y + 2, w * .12, h - 4);
    box(ctx, x + 25, y + 57, w * .66, 99, 5, '#FFFFFF', C.line, 1.5);
    label(ctx, 'ORDER 0482', x + 38, y + 78, 16, C.ink, 'left', w * .66 - 26, 700);
    barcode(ctx, x + 38, y + 98, w * .66 - 28, 24);
    line(ctx, x + 38, y + 139, x + 130, y + 139, C.muted, 2);
  }
  function shield(ctx, x, y, size, progress = 1) {
    ctx.beginPath(); ctx.moveTo(x, y - size * .5); ctx.lineTo(x + size * .4, y - size * .30);
    ctx.lineTo(x + size * .36, y + size * .12); ctx.quadraticCurveTo(x + size * .25, y + size * .36, x, y + size * .53);
    ctx.quadraticCurveTo(x - size * .25, y + size * .36, x - size * .36, y + size * .12); ctx.lineTo(x - size * .4, y - size * .30); ctx.closePath();
    ctx.fillStyle = blend(C.paper, C.green, .13); ctx.fill(); ctx.strokeStyle = C.ink; ctx.lineWidth = 3; ctx.stroke();
    if (progress > .0001) check(ctx, x, y + size * .03, size * .43, C.green, progress);
  }
  function lock(ctx, x, y, size, p = 1) {
    const lift = (1 - p) * size * .17;
    ctx.beginPath(); ctx.moveTo(x - size * .23, y - size * .02); ctx.lineTo(x - size * .23, y - size * .19 - lift);
    ctx.bezierCurveTo(x - size * .23, y - size * .56 - lift, x + size * .23, y - size * .56 - lift, x + size * .23, y - size * .19 - lift);
    ctx.lineTo(x + size * .23, y - size * .02 - lift); ctx.strokeStyle = C.ink; ctx.lineWidth = size * .065; ctx.stroke();
    box(ctx, x - size * .38, y - size * .06, size * .76, size * .56, size * .09, C.paper, C.ink, 3);
    circle(ctx, x, y + size * .18, size * .07, C.accent); line(ctx, x, y + size * .23, x, y + size * .34, C.accent, size * .06);
  }
  function statusCaption(ctx, x, y, text, t) {
    activity(ctx, x + 13, y, t, 10); label(ctx, text, x + 38, y, 17, C.muted, 'left', 365, 500);
  }
  function paint(ctx, cycleT, sceneProgress) {

    const t = cycleT, s = state(t, 8, 13);
    header(ctx, 'Modern contactless checkout', 'A clear payment flow from card reading to printed receipt.', t);
    counter(ctx);
    box(ctx, 170, 278, 420, 143, 22, C.paper, C.line, 3);
    label(ctx, 'PAYMENT METHOD', 200, 311, 16, C.muted, 'left', 360, 700);
    label(ctx, 'Contactless card', 200, 354, 28, C.ink, 'left', 360, 700);
    label(ctx, 'Present near the reader', 200, 393, 18, C.muted, 'left', 360, 400);
    const p = travel(t, 4, 7.8, 16.8, 19.7);
    paymentCard(ctx, mix(240, 492, p), 487);
    terminal(ctx, 820, 240, t, {state: s});
    summary(ctx, 1290, 278, 480, 294, {rows: [['Order', '0482'], ['Items', '3'], ['Method', 'Contactless']]});
    printer(ctx, 1360, 640, t, {amount: '$48.90'});
    statusCaption(ctx, 236, 742, 'Contactless card payment', t);
    badge(ctx, 240, 799, 310, 46, ['READY TO TAP', 'READING CARD', 'APPROVED'][s.index], blend(C.accent, C.green, s.w[2]), s.alpha);

  }
  return {paint, background: C.bg};
})();

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 1;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width, height);
  if (!(width > 0 && height > 0 && minSide > 0)) return;
  const scale = Math.min(width / 1920, height / 1080, minSide / 1080);
  const cycleT = Number.isFinite(loopT) ? (loopT < 0 ? loopT + duration : loopT) : 0;
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.globalAlpha = 1; ctx.globalCompositeOperation = 'source-over';
  ctx.shadowBlur = 0; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 0; ctx.shadowColor = 'rgba(0,0,0,0)';
  ctx.filter = 'none'; ctx.lineCap = 'round'; ctx.lineJoin = 'round'; ctx.miterLimit = 2;
  ctx.fillStyle = POS_SCENE_01.background; ctx.fillRect(0, 0, width, height);
  ctx.translate((width - 1920 * scale) / 2, (height - 1080 * scale) / 2); ctx.scale(scale, scale);
  POS_SCENE_01.paint(ctx, cycleT, currentScene === 0 ? sceneProgress : cycleT / duration);
  ctx.restore();
}
draw.duration = 20;
draw.sceneCount = 1;
draw.loop = true;
draw.meta = Object.freeze({title: 'Contactless Card Payment at a Modern Checkout Terminal', width: 3840, height: 2160, fps: 60, duration: 20, sceneCount: 1, loop: true, humanFigures: false});
draw.exportSettings = Object.freeze({width: 3840, height: 2160, fps: 60, videoBitrate: 100000000, minimumVideoBitrate: 100000000});
if (typeof module !== 'undefined' && module.exports) module.exports = draw;

/* Mobile Wallet Payment with a Contactless POS Reader
